(function(root){'use strict';
function forecast(rows,refs,ft=1,fi=1){if(!Number.isFinite(ft)||!Number.isFinite(fi)||ft<0||fi<0)throw Error('Fatores de projeção devem ser positivos ou zero.');const seen=new Set();for(const r of rows.filter(r=>r.include)){if(!r.ceg||!r.ceg.startsWith('UHE.'))throw Error('CEG ausente ou inválido: '+r.name);if(seen.has(r.ceg))throw Error('CEG duplicado no universo SIN: '+r.name);seen.add(r.ceg);if(!Number.isInteger(r.n)||r.n<=0||!Number.isInteger(r.band)||r.band<1||r.band>5||![r.teif,r.ip].every(v=>Number.isFinite(v)&&v>=0&&v<=100))throw Error('Linha SIN inválida: '+r.name)}return refs.map((ref,k)=>{const group=rows.filter(r=>r.include&&r.band===k+1),n=group.reduce((s,r)=>s+r.n,0);if(!n)throw Error('Sem amostra válida na faixa '+(k+1));const baseT=group.reduce((s,r)=>s+r.teif*r.n,0)/n,baseI=group.reduce((s,r)=>s+r.ip*r.n,0)/n,t=baseT*ft,i=baseI*fi;if(t>100||i>100)throw Error('Projeção acima de 100% na faixa '+(k+1));return {band:k+1,n,plants:group.length,baseT,baseI,teif:t,ip:i,disp:100*(1-t/100)*(1-i/100),ref:[ref[0],t,i]}})}
const api={forecast};root.ProjectionModel=api;if(typeof module!=='undefined')module.exports=api;
})(globalThis);
